import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.HashSet;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line = reader.readLine();
        while (line != null && line.trim().isEmpty()) {
            line = reader.readLine();
        }
        if (line == null) return;

        int n = Integer.parseInt(line.trim());
        String[] s = new String[n];
        int count = 0;
        while (count < n) {
            line = reader.readLine();
            if (line == null) break;
            StringTokenizer tokenizer = new StringTokenizer(line);
            while (tokenizer.hasMoreTokens()) {
                s[count++] = tokenizer.nextToken();
            }
        }

        HashSet<String> allSubstrings = new HashSet<>(100000);
        HashSet<String> suffixes = new HashSet<>(50000);
        HashSet<String> prefixes = new HashSet<>(50000);

        for (int k = 0; k < n; k++) {
            String current = s[k];
            int len = current.length();

            if (k > 0) {
                boolean invalid = false;

                // Caso 1: current é substring de alguma string anterior
                if (allSubstrings.contains(current)) {
                    invalid = true;
                }

                // Caso 2: current cruza a junção de duas strings anteriores
                if (!invalid) {
                    for (int j = 1; j < len; j++) {
                        String left = current.substring(0, j);
                        String right = current.substring(j);
                        if (suffixes.contains(left) && prefixes.contains(right)) {
                            invalid = true;
                            break;
                        }
                    }
                }

                if (invalid) {
                    System.out.println(current);
                    return;
                }
            }

            // Adiciona prefixos
            for (int i = 1; i <= len; i++) {
                prefixes.add(current.substring(0, i));
            }

            // Adiciona sufixos
            for (int i = 0; i < len; i++) {
                suffixes.add(current.substring(i));
            }

            // Adiciona todas as substrings
            for (int i = 0; i < len; i++) {
                for (int j = i + 1; j <= len; j++) {
                    allSubstrings.add(current.substring(i, j));
                }
            }
        }

        System.out.println("ok");
    }
}
